"""Load only the pinned, patched Turbo-GNN build generated by our builder."""
from functools import lru_cache
import hashlib
import json
from pathlib import Path


@lru_cache(maxsize=1)
def verified_turbo():
    import turbo_gnn
    expected=json.loads((Path(__file__).parents[1]/'TURBO_GNN_MANIFEST.json').read_text())
    package=Path(turbo_gnn.__file__).parent
    try:
        stamp=json.loads((package/'netcc_rl_build.json').read_text())
        if any(stamp[key]!=expected[key] for key in ('commit','patch_sha256')):
            raise ValueError('source/patch mismatch')
        if set(stamp['files'])!={'_functions.py', 'ops.py', '_kernels.py', *[p.name for p in package.glob('_C*.so')]}:
            raise ValueError('extension files mismatch')
        for name,digest in stamp['files'].items():
            if hashlib.sha256((package/name).read_bytes()).hexdigest()!=digest:
                raise ValueError(f'changed extension file: {name}')
    except (OSError,ValueError,KeyError) as error:
        raise RuntimeError('Unverified Turbo-GNN build; use scripts/build_turbo.py with the pinned compatibility patch') from error
    return turbo_gnn
